package com.asmj.marketplace.job.controller;
import com.asmj.marketplace.job.model.JobListing; import com.asmj.marketplace.job.repository.JobListingRepository; import com.asmj.marketplace.post.repository.PostRepository; import com.asmj.marketplace.post.model.Post; import com.asmj.marketplace.common.response.ApiResponse; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/admin/jobs") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')") public class JobAdminController { private final JobListingRepository jobs; private final PostRepository posts;
 @GetMapping public ApiResponse<List<JobListing>> all(){return ApiResponse.ok("Jobs",jobs.findAll());}
 @PutMapping("/{id}/approval") public ApiResponse<JobListing> approval(@PathVariable String id,@RequestParam boolean approved,@RequestParam(required=false) String reason){JobListing j=jobs.findById(id).orElseThrow(()->new IllegalArgumentException("Job not found"));Post p=posts.findById(j.getPostId()).orElseThrow(()->new IllegalArgumentException("Listing not found"));p.setApprovalStatus(approved?Post.PostStatus.APPROVED:Post.PostStatus.REJECTED);p.setStatus(approved?Post.PostStatus.PUBLISHED:Post.PostStatus.REJECTED);p.setUpdatedAt(Instant.now());posts.save(p);return ApiResponse.ok(approved?"Job approved":"Job rejected",j);}
}
